---@class PagleNS
local ns = select(2, ...)

-- The Refresh ticket's icon (#466), added to ns.ATLASES as "Ticket": where its sprite sits in its texture under
-- media/ticket/, for the "Refresh +N" stamp of an Announcement (REF-R7). The Tackle Board has its own copy of the same
-- art (a Module reaches none of Core's files, ADR 0001). Generated by scripts/ticket-art.py from
-- data/art/ticket/src/ticket.svg; don't edit by hand. The rectangle is in texels, `scale` texels per UI unit; `box` is the
-- drawn element inside the sprite in UI units (x, y from its top left, then w, h). The texture is a BLP (BLP2,
-- uncompressed BGRA, with its mipmaps) made from data/art/ticket/tga/Ticket.tga by scripts/encode-blp.py --raw.

local DIR = "Interface\\AddOns\\Pagle\\media\\ticket\\"

ns.ATLASES = ns.ATLASES or {}

---@type PagleAtlas
ns.ATLASES.Ticket = {
	file = DIR .. "Ticket",
	width = 128,
	height = 64,
	scale = 4,
	sprites = {
		ticket = { x = 2, y = 2, w = 80, h = 56, box = { 0, 0, 20, 14 } },
	},
}
